export function subjectsOf(course){return [...new Set((Array.isArray(course?.subjects)?course.subjects:[]).filter(s=>typeof s==='string'&&s.trim()).map(s=>s.trim()))];}
export function validateSubjects(mode,values){const subjects=values.map(s=>String(s).trim()).filter(Boolean);if(!['single','multiple'].includes(mode))throw Error('Escolha uma ou várias disciplinas.');if(new Set(subjects.map(s=>s.toLocaleLowerCase('pt-BR'))).size!==subjects.length)throw Error('Não repita o nome de uma disciplina.');if(subjects.some(s=>s.length>120)||subjects.length>100)throw Error('Informe até 100 disciplinas, com nomes de até 120 caracteres.');if(mode==='single'&&subjects.length!==1)throw Error('Informe o nome da única disciplina.');if(mode==='multiple'&&subjects.length<2)throw Error('Informe pelo menos duas disciplinas, uma por linha.');return subjects;}
export function assertSubject(course,subject){if(!subjectsOf(course).includes(subject))throw Error('Selecione uma disciplina cadastrada neste curso.');return subject;}
